package studyfix.assignment.persistence;

import studyfix.Identity;
import studyfix.assignment.model.Exercise;
import studyfix.assignment.service.BuilderProblem;
import java.sql.*;
import java.util.*;
import static studyfix.assignment.protocol.AssignmentJson.*;
import studyfix.assignment.persistence.ProblemBuilderRepository.Failure;

/** Additive authoring workflow; published rows are immutable and reuse the OJ judge tables. */
public final class BuilderWorkflowRepository {
 private final AssignmentRepository repo;private final ProblemBuilderRepository drafts;
 public Map<String,Object> snapshot(String exercise)throws SQLException{try(Connection c=repo.open();PreparedStatement p=c.prepareStatement("SELECT snapshot_json FROM p3_builder_publications WHERE exercise_id=?")){p.setString(1,exercise);try(ResultSet r=p.executeQuery()){return r.next()?map(parse(r.getString(1))):Map.of();}}}
 public BuilderWorkflowRepository(AssignmentRepository repo,ProblemBuilderRepository drafts)throws SQLException{
  this.repo=repo;this.drafts=drafts;
  try(Connection c=repo.open();Statement s=c.createStatement()){
   s.executeUpdate("CREATE TABLE IF NOT EXISTS p3_builder_workflow(draft_id TEXT PRIMARY KEY REFERENCES p3_builder_drafts(id),state TEXT NOT NULL DEFAULT 'DRAFT',reviewer_id TEXT NOT NULL DEFAULT '',review_hash TEXT NOT NULL DEFAULT '',approved_hash TEXT NOT NULL DEFAULT '',actor_id TEXT NOT NULL DEFAULT '',updated_at INTEGER NOT NULL)");
   s.executeUpdate("CREATE TABLE IF NOT EXISTS p3_builder_jobs(id TEXT PRIMARY KEY,draft_id TEXT NOT NULL REFERENCES p3_builder_drafts(id),content_hash TEXT NOT NULL,status TEXT NOT NULL,progress TEXT NOT NULL,result_json TEXT NOT NULL DEFAULT '{}',created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL)");
   s.executeUpdate("CREATE INDEX IF NOT EXISTS p3_builder_jobs_draft ON p3_builder_jobs(draft_id,created_at)");
   s.executeUpdate("CREATE TABLE IF NOT EXISTS p3_builder_publications(draft_id TEXT NOT NULL REFERENCES p3_builder_drafts(id),content_hash TEXT NOT NULL,exercise_id TEXT NOT NULL UNIQUE REFERENCES p3_exercises(id),snapshot_json TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(draft_id,content_hash))");
   s.executeUpdate("CREATE TABLE IF NOT EXISTS p3_builder_public_assets(asset_id TEXT NOT NULL REFERENCES p3_builder_assets(id),exercise_id TEXT NOT NULL REFERENCES p3_exercises(id),PRIMARY KEY(asset_id,exercise_id))");
   s.executeUpdate("UPDATE p3_builder_jobs SET status='INTERRUPTED',progress='Server khởi động lại; hãy kiểm định lại.' WHERE status IN ('QUEUED','RUNNING')");
  }
 }
 private Map<String,Object> flow(Connection c,String id,String hash)throws SQLException{
  try(PreparedStatement p=c.prepareStatement("SELECT * FROM p3_builder_workflow WHERE draft_id=?")){p.setString(1,id);try(ResultSet r=p.executeQuery()){if(r.next())return mapOf("state",hash.equals(r.getString("review_hash"))?r.getString("state"):"DRAFT","reviewerId",r.getString("reviewer_id"),"approved",hash.equals(r.getString("approved_hash")),"updatedAt",r.getLong("updated_at"));}}
  return mapOf("state","DRAFT","reviewerId","","approved",false);
 }
 public Map<String,Object> status(Identity who,String id)throws SQLException{try(Connection c=repo.open()){var d=drafts.owned(c,who,id);var out=flow(c,id,text(d,"contentHash",""));out.put("validation",drafts.latestCheck(who,id,"VALIDATION"));List<Map<String,Object>> history=new ArrayList<>();try(PreparedStatement p=c.prepareStatement("SELECT id,content_hash,status,progress,result_json,created_at FROM p3_builder_jobs WHERE draft_id=? ORDER BY created_at DESC LIMIT 20")){p.setString(1,id);try(ResultSet r=p.executeQuery()){while(r.next())history.add(mapOf("id",r.getString(1),"contentHash",r.getString(2),"status",r.getString(3),"progress",r.getString(4),"result",history.isEmpty()?parse(r.getString(5)):mapOf("kind","HISTORY","passed",map(parse(r.getString(5))).get("passed")),"createdAt",r.getLong(6)));}}out.put("history",history);return out;}}
 public String createJob(Identity who,String id,String hash)throws SQLException{
  try(Connection c=repo.open();Statement tx=c.createStatement()){tx.execute("BEGIN IMMEDIATE");try{var d=drafts.owned(c,who,id);if(!hash.equals(d.get("contentHash")))throw new Failure("CONFLICT","Nháp đã đổi trước khi xếp hàng kiểm định.");
   try(PreparedStatement p=c.prepareStatement("SELECT id FROM p3_builder_jobs WHERE draft_id=? AND status IN ('QUEUED','RUNNING')")){p.setString(1,id);try(ResultSet r=p.executeQuery()){if(r.next())throw new Failure("BUSY","Bản nháp đang có lượt chạy; chờ hoàn tất trước khi chạy tiếp.");}}
   String job=UUID.randomUUID().toString();long now=System.currentTimeMillis();try(PreparedStatement p=c.prepareStatement("INSERT INTO p3_builder_jobs VALUES(?,?,?,'QUEUED','Đang chờ môi trường kiểm định.','{}',?,?)")){p.setString(1,job);p.setString(2,id);p.setString(3,hash);p.setLong(4,now);p.setLong(5,now);p.executeUpdate();}tx.execute("COMMIT");return job;
  }catch(SQLException|RuntimeException e){tx.execute("ROLLBACK");throw e;}}}
 public void job(String job,String status,String progress,Map<String,Object> result)throws SQLException{try(Connection c=repo.open();PreparedStatement p=c.prepareStatement("UPDATE p3_builder_jobs SET status=?,progress=?,result_json=?,updated_at=? WHERE id=?")){p.setString(1,status);p.setString(2,progress);p.setString(3,stringify(result));p.setLong(4,System.currentTimeMillis());p.setString(5,job);p.executeUpdate();}}
 private static Map<String,Object> currentValidation(Connection c,String id,String hash)throws SQLException{
  try(PreparedStatement p=c.prepareStatement("SELECT result_json FROM p3_builder_checks WHERE draft_id=? AND content_hash=? AND check_kind='VALIDATION' ORDER BY id DESC LIMIT 1")){p.setString(1,id);p.setString(2,hash);try(ResultSet r=p.executeQuery()){if(r.next()){var v=map(parse(r.getString(1)));if(Boolean.TRUE.equals(v.get("passed")))return v;}}}
  throw new Failure("VALIDATION_REQUIRED","Chưa kiểm định đạt hoặc nội dung đã đổi. Hãy kiểm định lại.");
 }
 private void writeFlow(Connection c,String id,String state,String reviewer,String hash,String approved,String actor)throws SQLException{try(PreparedStatement p=c.prepareStatement("INSERT INTO p3_builder_workflow VALUES(?,?,?,?,?,?,?) ON CONFLICT(draft_id) DO UPDATE SET state=excluded.state,reviewer_id=excluded.reviewer_id,review_hash=excluded.review_hash,approved_hash=excluded.approved_hash,actor_id=excluded.actor_id,updated_at=excluded.updated_at")){p.setString(1,id);p.setString(2,state);p.setString(3,reviewer);p.setString(4,hash);p.setString(5,approved);p.setString(6,actor);p.setLong(7,System.currentTimeMillis());p.executeUpdate();}}
 public void review(Identity who,String id,int revision,String reviewer,boolean approveSelf)throws SQLException{
  try(Connection c=repo.open();Statement tx=c.createStatement()){tx.execute("BEGIN IMMEDIATE");try{var d=drafts.owned(c,who,id);if(integer(d,"revision",0)!=revision)throw new Failure("CONFLICT","Nháp đã thay đổi.");String hash=text(d,"contentHash","");currentValidation(c,id,hash);if(approveSelf){var flow=flow(c,id,hash);if("IN_REVIEW".equals(flow.get("state"))&&!who.userId().equals(flow.get("reviewerId")))throw new Failure("FORBIDDEN","Đã gửi người khác duyệt; không tự ghi đè kết quả duyệt.");reviewer=who.userId();}writeFlow(c,id,approveSelf?"APPROVED":"IN_REVIEW",reviewer,hash,approveSelf?hash:"",who.userId());tx.execute("COMMIT");}catch(SQLException|RuntimeException e){tx.execute("ROLLBACK");throw e;}}
 }
 public List<Map<String,Object>> reviews(Identity who)throws SQLException{
  if(who.role()!=Identity.Role.TEACHER)throw new Failure("FORBIDDEN","Teacher only");List<Map<String,Object>> out=new ArrayList<>();try(Connection c=repo.open();PreparedStatement p=c.prepareStatement("SELECT d.id,d.code,d.payload_json,d.revision,w.review_hash,d.content_hash FROM p3_builder_workflow w JOIN p3_builder_drafts d ON d.id=w.draft_id WHERE w.reviewer_id=? AND w.state='IN_REVIEW' AND d.deleted=0 ORDER BY w.updated_at DESC LIMIT 100")){p.setString(1,who.userId());try(ResultSet r=p.executeQuery()){while(r.next())if(r.getString(5).equals(r.getString(6)))out.add(mapOf("id",r.getString(1),"code",r.getString(2),"title",text(map(parse(r.getString(3))),"title",""),"revision",r.getInt(4),"contentHash",r.getString(6)));}}return out;
 }
 public Map<String,Object> reviewGet(Identity who,String id)throws SQLException{
  if(who.role()!=Identity.Role.TEACHER)throw new Failure("FORBIDDEN","Teacher only");try(Connection c=repo.open();PreparedStatement p=c.prepareStatement("SELECT d.owner_id,d.content_hash,w.review_hash,w.state,w.reviewer_id FROM p3_builder_drafts d JOIN p3_builder_workflow w ON w.draft_id=d.id WHERE d.id=? AND d.deleted=0")){p.setString(1,id);try(ResultSet r=p.executeQuery()){if(!r.next()||!who.userId().equals(r.getString(5))||!r.getString(2).equals(r.getString(3))||!"IN_REVIEW".equals(r.getString(4)))throw new Failure("FORBIDDEN","Không có yêu cầu duyệt hợp lệ dành cho bạn.");var draft=drafts.owned(c,new Identity(r.getString(1),"","",Identity.Role.TEACHER),id);draft.put("validation",currentValidation(c,id,r.getString(2)));return draft;}}}
 public void decide(Identity who,String id,String hash,boolean approve)throws SQLException{
  try(Connection c=repo.open();Statement tx=c.createStatement()){tx.execute("BEGIN IMMEDIATE");try{var d=reviewGet(who,id);if(!hash.equals(d.get("contentHash")))throw new Failure("CONFLICT","Nội dung đã thay đổi sau khi gửi duyệt.");currentValidation(c,id,hash);writeFlow(c,id,approve?"APPROVED":"DRAFT",who.userId(),hash,approve?hash:"",who.userId());tx.execute("COMMIT");}catch(SQLException|RuntimeException e){tx.execute("ROLLBACK");throw e;}}}
 public Map<String,Object> publish(Identity who,String id,int revision)throws SQLException{
  try(Connection c=repo.open();Statement tx=c.createStatement()){tx.execute("BEGIN IMMEDIATE");try{var d=drafts.owned(c,who,id);if(integer(d,"revision",0)!=revision)throw new Failure("CONFLICT","Nháp đã thay đổi.");String hash=text(d,"contentHash","");
   try(PreparedStatement p=c.prepareStatement("SELECT exercise_id FROM p3_builder_publications WHERE draft_id=? AND content_hash=?")){p.setString(1,id);p.setString(2,hash);try(ResultSet r=p.executeQuery()){if(r.next()){String existing=r.getString(1);tx.execute("COMMIT");return mapOf("exerciseId",existing,"reused",true);}}}
   Map<String,Object> payload=map(d.get("payload"));BuilderProblem.require(payload,5);if(!"PUBLIC".equals(text(payload,"visibility","PRIVATE")))throw new Failure("INVALID_REQUEST","Chọn Phát hành công khai; riêng tư/chia sẻ giữ ở nháp hoặc gửi reviewer.");var validation=currentValidation(c,id,hash);if(!Boolean.TRUE.equals(flow(c,id,hash).get("approved")))throw new Failure("APPROVAL_REQUIRED","Cần duyệt nội dung trước khi phát hành.");
   String base=text(d,"baseExerciseId",""),code=text(payload,"code",""),root=code;int next=1;
   if(!base.isEmpty()){try(PreparedStatement p=c.prepareStatement("SELECT root_id,revision,owner_id,is_current,deleted FROM p3_question_bank WHERE exercise_id=?")){p.setString(1,base);try(ResultSet r=p.executeQuery()){if(!r.next()||(!r.getString(3).isBlank()&&!who.userId().equals(r.getString(3)))||!r.getBoolean(4)||r.getBoolean(5)||r.getInt(2)!=integer(d,"baseRevision",0))throw new Failure("CONFLICT","Phiên bản gốc đã đổi hoặc bạn không có quyền sửa.");root=r.getString(1);next=r.getInt(2)+1;}}}
   else{try(PreparedStatement p=c.prepareStatement("SELECT 1 FROM p3_question_bank WHERE display_code=?")){p.setString(1,code);try(ResultSet r=p.executeQuery()){if(r.next())throw new Failure("DUPLICATE_CODE","Mã bài đã có trong ngân hàng.");}}}
   String exerciseId=code.substring(0,Math.min(32,code.length()))+"_v"+next+"_"+UUID.randomUUID().toString().substring(0,8);Exercise e=BuilderProblem.exercise(payload,exerciseId);long now=System.currentTimeMillis();
   try(PreparedStatement p=c.prepareStatement("UPDATE p3_question_bank SET is_current=0 WHERE root_id=?")){p.setString(1,root);p.executeUpdate();}
   try(PreparedStatement p=c.prepareStatement("INSERT INTO p3_exercises(id,title,topic,difficulty,statement,input_format,output_format,constraints_text,template,hints,reference_solution,catalog_version,created_at,mode,starter_code,java_structure,entry_file) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)")){int n=1;for(String s:List.of(e.id(),e.title(),e.topic(),e.difficulty(),e.statement(),e.inputFormat(),e.outputFormat(),e.constraints(),e.template(),e.hints(),e.referenceSolution()))p.setString(n++,s);p.setInt(n++,next);p.setLong(n++,now);p.setString(n++,e.mode().name());p.setString(n++,e.starterCode());p.setString(n++,e.javaStructure());p.setString(n,e.entryFile());p.executeUpdate();}
   try(PreparedStatement p=c.prepareStatement("INSERT INTO p3_test_cases(exercise_id,ordinal_no,input_text,expected_output,weight,hidden) VALUES(?,?,?,?,?,?)")){int ordinal=0;for(var test:e.tests()){p.setString(1,exerciseId);p.setInt(2,++ordinal);p.setString(3,test.input());p.setString(4,test.expected());p.setInt(5,test.weight());p.setBoolean(6,test.hidden());p.addBatch();}p.executeBatch();}
   try(PreparedStatement p=c.prepareStatement("INSERT INTO p3_question_bank(exercise_id,root_id,display_code,owner_id,publication,revision,updated_at) VALUES(?,?,?,?,'PUBLISHED',?,?)")){p.setString(1,exerciseId);p.setString(2,root);p.setString(3,code);p.setString(4,who.userId());p.setInt(5,next);p.setLong(6,now);p.executeUpdate();}
   try(PreparedStatement p=c.prepareStatement("INSERT INTO p3_oj_exercises VALUES(?,?,?,?,?,?,?)")){p.setString(1,exerciseId);p.setString(2,"builder:"+hash);p.setString(3,code);p.setString(4,stringify(BuilderProblem.config(payload)));p.setString(5,stringify(mapOf("builderDraftId",id,"contentHash",hash,"visibility",text(payload,"visibility","PUBLIC"))));p.setString(6,stringify(validation));p.setLong(7,now);p.executeUpdate();}
   if(!base.isEmpty())try(PreparedStatement p=c.prepareStatement("UPDATE p3_question_week_items SET exercise_id=? WHERE exercise_id=?")){p.setString(1,exerciseId);p.setString(2,base);p.executeUpdate();}
   for(Object raw:list(payload.get("weekIds"))){String week=String.valueOf(raw);try(PreparedStatement p=c.prepareStatement("SELECT 1 FROM p3_question_weeks WHERE id=? AND owner_id=?")){p.setString(1,week);p.setString(2,who.userId());try(ResultSet r=p.executeQuery()){if(!r.next())throw new Failure("FORBIDDEN","Week không thuộc quyền quản lý của bạn.");}}try(PreparedStatement p=c.prepareStatement("INSERT OR IGNORE INTO p3_question_week_items VALUES(?,?,?)")){p.setString(1,week);p.setString(2,exerciseId);p.setLong(3,now);p.executeUpdate();}}
   Set<String> assets=new LinkedHashSet<>();String statement=text(map(payload.get("statement")),"description","");var matcher=java.util.regex.Pattern.compile("/api/problem-builder/assets/([A-Za-z0-9-]+)").matcher(statement);while(matcher.find())assets.add(matcher.group(1));for(Object raw:list(map(payload.get("statement")).get("attachments")))assets.add(text(map(raw),"id",""));
   for(String asset:assets)try(PreparedStatement p=c.prepareStatement("INSERT INTO p3_builder_public_assets SELECT id,? FROM p3_builder_assets WHERE id=? AND (draft_id=? OR EXISTS(SELECT 1 FROM p3_builder_public_assets old WHERE old.asset_id=p3_builder_assets.id AND old.exercise_id=?)) AND media_type IN ('image/png','image/jpeg','application/pdf')")){p.setString(1,exerciseId);p.setString(2,asset);p.setString(3,id);p.setString(4,base);if(p.executeUpdate()!=1)throw new Failure("INVALID_ASSET","Tài nguyên đề bài không thuộc nháp hoặc không được phép công khai.");}
   try(PreparedStatement p=c.prepareStatement("INSERT INTO p3_builder_publications VALUES(?,?,?,?,?)")){p.setString(1,id);p.setString(2,hash);p.setString(3,exerciseId);p.setString(4,stringify(payload));p.setLong(5,now);p.executeUpdate();}
   writeFlow(c,id,"PUBLISHED",text(flow(c,id,hash),"reviewerId",who.userId()),hash,hash,who.userId());tx.execute("COMMIT");return mapOf("exerciseId",exerciseId,"revision",next,"reused",false);
  }catch(SQLException|RuntimeException e){tx.execute("ROLLBACK");throw e;}}}
 public void archive(Identity who,String id,int revision)throws SQLException{try(Connection c=repo.open();Statement tx=c.createStatement()){tx.execute("BEGIN IMMEDIATE");try{var d=drafts.owned(c,who,id);if(integer(d,"revision",0)!=revision)throw new Failure("CONFLICT","Nháp đã thay đổi.");String hash=text(d,"contentHash","");try(PreparedStatement p=c.prepareStatement("UPDATE p3_question_bank SET deleted=1 WHERE exercise_id IN (SELECT exercise_id FROM p3_builder_publications WHERE draft_id=? AND content_hash=?)")){p.setString(1,id);p.setString(2,hash);if(p.executeUpdate()==0)throw new Failure("NOT_FOUND","Nội dung này chưa phát hành.");}writeFlow(c,id,"ARCHIVED","",hash,"",who.userId());tx.execute("COMMIT");}catch(SQLException|RuntimeException e){tx.execute("ROLLBACK");throw e;}}}
}
